/**
 * src/components/CredentialForm.tsx
 *
 * 可复用的单组 Provider 凭据表单。
 * 同时用于「首次配置向导」和「设置页·模型服务」。
 *
 * 提供：provider 选择、API Key 输入（已保存者脱敏只读 + 「更换密钥」）、
 * model_id combobox（推荐清单 + **任意手填**）、单价填写（CNY / 1k token）、
 * Base URL（占位提示默认值）、默认组标记、删除按钮。
 */

import { useState, useCallback, useMemo } from "react";
import {
  useCredentialStore,
  getProviderMeta,
  emptyCredential,
  findSystemPrice,
  recommendedForProvider,
  isMaskedKey,
  type ProviderCredential,
  type LLMProvider,
} from "../store/credentialStore";
import type { ModelPriceEntry, ProviderMeta } from "../types/api";
import type { VerifyResult } from "../store/credentialStore";

// ── Props ─────────────────────────────────────────────────────────────────

interface CredentialFormProps {
  /** 当前凭据数据 */
  credential: ProviderCredential;
  /** 凭据变更回调 */
  onChange: (cred: ProviderCredential) => void;
  /** 删除该组凭据（undefined = 不显示删除按钮） */
  onDelete?: () => void;
  /** 该校验结果（undefined = 未校验 / idle） */
  verifyResult?: VerifyResult;
  /** 是否正在整组校验中（禁用控件） */
  verifying?: boolean;
  /** 是否为默认组 */
  isDefault: boolean;
  /** 设置该组为默认 */
  onSetDefault?: () => void;
  /**
   * 其他卡片已占用的 `(provider, model_id)` 组合，用于即时标红重复。
   *
   * ⚠️ 不再是「已用 provider 列表」：主键已改为 `(provider, model_id)`，
   *    同一 provider 可配 N 个模型（PRD G1），provider 本身不构成冲突。
   */
  usedKeys?: string[];
  /** 是否显示 provider 下拉（向导首组隐藏，仅展示） */
  showProviderSelect?: boolean;
  /** 表单索引（用于显示序号） */
  index?: number;
  /**
   * 系统预置 provider 元信息（从后端 catalog 拉取）。
   * 未传时从 useCredentialStore 读；空数组 = catalog 未拉到，控件 disabled。
   */
  providerCatalog?: ProviderMeta[];
  /**
   * 该卡片是否为「已保存」态。
   * 已保存 → api_key 走脱敏只读 + 「更换密钥」流程（PRD §4.3.1-3）。
   */
  isSaved?: boolean;
  /**
   * 用户是否已点「更换密钥」并在重填。
   * 由父组件持有：它决定提交体带不带 api_key（R3），是保存语义的一部分，
   * 不能只活在卡片内部 state 里。
   */
  keyChanged?: boolean;
  /** 切换「更换密钥」态 */
  onKeyChangedToggle?: (changed: boolean) => void;
}

// ── 样式 ─────────────────────────────────────────────────────────────────

const S = {
  card: {
    background: "var(--bg-elevated)",
    border: "1px solid var(--border-default)",
    borderRadius: "var(--radius-md)",
    padding: "var(--space-4) var(--space-5)",
    marginBottom: "var(--space-3)",
    transition: "border-color var(--duration-fast)",
    position: "relative" as const,
  } as React.CSSProperties,

  // ⚠️ 覆盖态一律用 border 简写：基础样式（card/select/input）用的是 border 简写，
  //    这里若只写 borderColor，条件展开时 React 会在"移除 borderColor 但保留 border"
  //    之间来回 diff → 控制台 shorthand 冲突告警 + 边框颜色可能不还原。
  cardError: {
    border: "1px solid var(--danger)",
  } as React.CSSProperties,

  cardDefault: {
    border: "1px solid var(--accent)",
  } as React.CSSProperties,

  cardHeader: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    marginBottom: "var(--space-3)",
  } as React.CSSProperties,

  providerLabel: {
    fontSize: "var(--text-sm)",
    fontWeight: 600,
    color: "var(--text-primary)",
    display: "flex",
    alignItems: "center",
    gap: "var(--space-2)",
  } as React.CSSProperties,

  providerBadge: {
    display: "inline-flex",
    alignItems: "center",
    padding: "2px 8px",
    borderRadius: "var(--radius-xs)",
    fontSize: "var(--text-2xs)",
    fontWeight: 600,
    background: "rgba(124,58,237,0.12)",
    color: "var(--accent-soft)",
  } as React.CSSProperties,

  defaultBadge: {
    display: "inline-flex",
    alignItems: "center",
    padding: "2px 8px",
    borderRadius: "var(--radius-xs)",
    fontSize: "var(--text-2xs)",
    fontWeight: 600,
    background: "rgba(34,197,94,0.12)",
    color: "var(--success)",
  } as React.CSSProperties,

  fieldGroup: {
    marginBottom: "var(--space-3)",
  } as React.CSSProperties,

  label: {
    display: "block",
    fontSize: "var(--text-xs)",
    fontWeight: 500,
    color: "var(--text-secondary)",
    marginBottom: "var(--space-1)",
  } as React.CSSProperties,

  select: {
    width: "100%",
    padding: "8px 12px",
    fontSize: "var(--text-base)",
    fontFamily: "inherit",
    background: "var(--bg-panel)",
    border: "1px solid var(--border-default)",
    borderRadius: "var(--radius-sm)",
    color: "var(--text-primary)",
    outline: "none",
    cursor: "pointer",
    transition: "border-color var(--duration-fast)",
    appearance: "none" as const,
    WebkitAppearance: "none" as const,
  } as React.CSSProperties,

  selectFocus: {
    border: "1px solid var(--border-focus)",
    boxShadow: "0 0 0 3px rgba(124,58,237,0.10)",
  } as React.CSSProperties,

  inputWrap: {
    position: "relative" as const,
  } as React.CSSProperties,

  input: {
    width: "100%",
    padding: "8px 12px",
    fontSize: "var(--text-base)",
    fontFamily: "inherit",
    background: "var(--bg-panel)",
    border: "1px solid var(--border-default)",
    borderRadius: "var(--radius-sm)",
    color: "var(--text-primary)",
    outline: "none",
    transition: "border-color var(--duration-fast)",
  } as React.CSSProperties,

  inputError: {
    border: "1px solid var(--danger)",
  } as React.CSSProperties,

  inputRight: {
    position: "absolute" as const,
    right: 4,
    top: "50%",
    transform: "translateY(-50%)",
    display: "flex",
    alignItems: "center",
    gap: 4,
  } as React.CSSProperties,

  toggleBtn: {
    padding: "3px 8px",
    fontSize: "var(--text-2xs)",
    color: "var(--text-tertiary)",
    background: "transparent",
    border: "1px solid var(--border-default)",
    borderRadius: "var(--radius-xs)",
    cursor: "pointer",
    fontFamily: "inherit",
    transition: "color var(--duration-fast), border-color var(--duration-fast)",
  } as React.CSSProperties,

  placeholder: {
    fontSize: "var(--text-2xs)",
    color: "var(--text-muted)",
    marginTop: "var(--space-1)",
  } as React.CSSProperties,

  errorText: {
    fontSize: "var(--text-xs)",
    color: "var(--danger)",
    marginTop: "var(--space-1)",
    display: "flex",
    alignItems: "center",
    gap: 4,
  } as React.CSSProperties,

  verifyingText: {
    fontSize: "var(--text-xs)",
    color: "var(--accent-soft)",
    marginTop: "var(--space-1)",
  } as React.CSSProperties,

  footer: {
    display: "flex",
    alignItems: "center",
    justifyContent: "space-between",
    marginTop: "var(--space-4)",
    paddingTop: "var(--space-3)",
    borderTop: "1px solid var(--border-subtle)",
  } as React.CSSProperties,

  footerActions: {
    display: "flex",
    alignItems: "center",
    gap: "var(--space-2)",
  } as React.CSSProperties,

  actionBtn: {
    padding: "4px 12px",
    fontSize: "var(--text-xs)",
    fontFamily: "inherit",
    borderRadius: "var(--radius-sm)",
    border: "1px solid var(--border-default)",
    background: "transparent",
    color: "var(--text-secondary)",
    cursor: "pointer",
    transition: "all var(--duration-fast)",
  } as React.CSSProperties,

  defaultBtn: {
    padding: "4px 12px",
    fontSize: "var(--text-xs)",
    fontFamily: "inherit",
    borderRadius: "var(--radius-sm)",
    border: "1px solid var(--success)",
    background: "rgba(34,197,94,0.08)",
    color: "var(--success)",
    cursor: "pointer",
    fontWeight: 500,
    transition: "all var(--duration-fast)",
  } as React.CSSProperties,

  deleteBtn: {
    padding: "4px 12px",
    fontSize: "var(--text-xs)",
    fontFamily: "inherit",
    borderRadius: "var(--radius-sm)",
    border: "1px solid rgba(239,68,68,0.25)",
    background: "transparent",
    color: "var(--danger)",
    cursor: "pointer",
    transition: "all var(--duration-fast)",
  } as React.CSSProperties,

  guideLink: {
    fontSize: "var(--text-2xs)",
    color: "var(--accent)",
    textDecoration: "none",
    cursor: "pointer",
    marginLeft: "auto",
  } as React.CSSProperties,

  // ── model_id combobox ──
  comboWrap: {
    position: "relative" as const,
  } as React.CSSProperties,

  comboList: {
    position: "absolute" as const,
    top: "calc(100% + 2px)",
    left: 0,
    right: 0,
    zIndex: 20,
    maxHeight: 220,
    overflowY: "auto" as const,
    background: "var(--bg-elevated)",
    border: "1px solid var(--border-default)",
    borderRadius: "var(--radius-sm)",
    boxShadow: "0 8px 24px rgba(0,0,0,0.28)",
    padding: "4px 0",
  } as React.CSSProperties,

  comboItem: {
    display: "flex",
